import { IsEmail, IsNotEmpty, IsString, IsUUID, MaxLength } from 'class-validator'

/**
 * Body of `POST /api/admin/staff`. The account is provisioned only: there is no password, and the person claims it at
 * their first Clerk sign-in with this email. `staff_code` is generated by the database.
 *
 * `reason` is only type-checked here. The service applies the length rule so it can answer with `REASON_REQUIRED`
 * instead of a generic validation error.
 */
export class CreateStaffDto {
  @IsString()
  @IsNotEmpty()
  @MaxLength(100)
  first_name: string

  @IsString()
  @IsNotEmpty()
  @MaxLength(100)
  last_name: string

  @IsEmail()
  @MaxLength(254)
  email: string

  @IsUUID()
  role_id: string

  @IsString()
  @MaxLength(500)
  reason: string
}
